<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Cetak Daftar Ringkas</title><style>body{font-family:Arial,sans-serif;color:#111}table{width:100%;border-collapse:collapse}td,th{border:1px solid #555;padding:6px}.no-print{margin-bottom:16px}.empty{text-align:center;padding:24px;color:#555}.filters{font-size:12px;color:#555}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="window.print()">Cetak Daftar Ringkas</button><h1>Daftar Ringkas Jadwal Pelajaran</h1><p>Menampilkan daftar jadwal dalam bentuk tabel sederhana.</p><p>MI Muslimat NU · Tanggal cetak {{ $printedAt->format('d/m/Y H:i') }}</p>@if(collect($filters)->filter()->isNotEmpty())<p class="filters">Filter yang digunakan: {{ collect($filters)->filter()->map(fn ($value, $key) => str_replace('_', ' ', $key).': '.$value)->join(' · ') }}</p>@endif<table><thead><tr><th>Hari</th><th>Jam</th><th>Kelas</th><th>Mata Pelajaran</th><th>Guru</th><th>Ruangan</th><th>Semester</th></tr></thead><tbody>@forelse($items as $s)<tr><td>{{ $s->day_of_week?->label() }}</td><td>{{ substr($s->starts_at,0,5) }}–{{ substr($s->ends_at,0,5) }}</td><td>{{ $s->classroom?->name }}</td><td>{{ $s->subject?->name }}</td><td>{{ $s->employee?->name ?? 'Belum ditetapkan' }}</td><td>{{ $s->room }}</td><td>{{ $s->semester?->name }}</td></tr>@empty<tr><td class="empty" colspan="7">Belum ada jadwal untuk pilihan tersebut.</td></tr>@endforelse</tbody></table></body></html>
